isVisible:
{{
  [
    Rating29Copy.value,
    Rating30Copy.value,
    Rating31Copy.value,
    Rating32Copy.value,
    Rating33Copy.value,
    Rating34Copy.value,
    Rating35Copy.value,
    Rating36Copy.value
  ].every(r => r >= 1)
}}

text:
{{
  (() => {
    const somma =
      Rating29Copy.value +
      Rating30Copy.value +
      Rating31Copy.value +
      Rating32Copy.value +
      Rating33Copy.value +
      Rating34Copy.value +
      Rating35Copy.value +
      Rating36Copy.value;

    return somma === 0 ? "" : (somma === 24 ? "IDONEO" : "NON IDONEO");
  })()
}}

textColor:
{{
  (() => {
    const somma =
      Rating29Copy.value +
      Rating30Copy.value +
      Rating31Copy.value +
      Rating32Copy.value +
      Rating33Copy.value +
      Rating34Copy.value +
      Rating35Copy.value +
      Rating36Copy.value;

    return somma === 0 ? "" : (somma === 24 ? "green" : "red");
  })()
}}
